// Extract subject and htmlBody from the newsletter agent's output
const rawOutput = $input.first().json.output || '';

let subject = '🎙️ Daily Voice Agent & AI Automation Intelligence Brief';
let htmlBody = '';

try {
  // Attempt to parse JSON if wrapped or raw
  const cleaned = rawOutput.replace(/```json/gi, '').replace(/```/g, '').trim();
  const parsed = JSON.parse(cleaned);
  if (parsed.subject) subject = parsed.subject;
  if (parsed.htmlBody) htmlBody = parsed.htmlBody;
  else if (parsed.html) htmlBody = parsed.html;
} catch (e) {
  // If not strict JSON, extract HTML content or use raw
  const htmlMatch = rawOutput.match(/<html[\s\S]*?<\/html>/i) || rawOutput.match(/<table[\s\S]*?<\/table>/i) || rawOutput.match(/<div[\s\S]*?<\/div>/i);
  if (htmlMatch) {
    htmlBody = htmlMatch[0];
  } else {
    htmlBody = rawOutput.replace(/```html/gi, '').replace(/```/g, '').trim();
  }
}

return [{
  json: {
    subject: subject,
    htmlBody: htmlBody,
    recipient: 'mudasiralibaloch56@gmail.com'
  }
}];
